package org.apache.commons.lang;

import junit.framework.TestCase;

public class AgentBRT_Lang_45_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        // Test case to reproduce the bug in the abbreviate method
        String input = "The quick brown fox jumps over the lazy dog";
        int lower = 10;
        int upper = 15;
        String appendToEnd = "...";

        // Expected behavior: abbreviate at the first space after lower limit
        // and append "..." if abbreviation occurs
        String expected = "The quick...";

        // Actual result from the buggy method
        String result = WordUtils.abbreviate(input, lower, upper, appendToEnd);

        // Assert that the result matches the expected output
        assertEquals("Abbreviation did not occur as expected", expected, result);
    }
}

